def handle(app, svc):
    resp = svc.apply(app)
    decision = resp.get("decision")
    limit = resp.get("limit", 0) or 0

    # Network referral rule: self_employed applicant with requested_limit above 7000
    # must go to manual review instead of being issued; a decline stays a decline.
    if app.get("employment") == "self_employed" and app.get("requested_limit", 0) > 7000:
        if decision == "decline":
            return {"action": "decline", "limit": 0}
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": limit}
    if decision == "decline":
        return {"action": "decline", "limit": 0}
    if decision == "refer":
        return {"action": "queue_review", "limit": 0}

    # Unknown decision: be safe, send to manual review rather than deciding.
    return {"action": "queue_review", "limit": 0}
